20	// distillTemplate returns the distillation prompt body shipped with the binary,
21	// with its YAML frontmatter stripped. The frontmatter is metadata for skill
22	// installers, not part of the prompt — and crucially the agent runners pass the
23	// prompt as a positional CLI argument, so a leading "---" would be parsed as an
24	// unknown flag and rejected. A missing template is a build error, not runtime.
25	func distillTemplate() (string, error) {
26		data, err := entirebrain.Templates.ReadFile(distillTemplateName)
27		if err != nil {
28			return "", fmt.Errorf("read distill template: %w", err)
29		}
30		return stripTemplateFrontmatter(string(data)), nil
31	}
32	
33	// stripTemplateFrontmatter removes a leading YAML frontmatter block
34	// ("---\n...\n---\n") and returns the body. Content without frontmatter is
35	// returned unchanged.
36	func stripTemplateFrontmatter(content string) string {
37		if !strings.HasPrefix(content, "---\n") && !strings.HasPrefix(content, "---\r\n") {
38			return content
39		}
40		lines := strings.Split(content, "\n")
41		for i := 1; i < len(lines); i++ {
42			if strings.TrimSpace(lines[i]) == "---" {
43				// Trim leading CR as well as LF: on Windows the template is checked out
44				// with CRLF endings, so splitting on "\n" leaves a stray "\r" on the
45				// blank line after the closing delimiter — trimming only "\n" would
46				// leave the body starting with "\r\n" (breaking the prefix the agent
47				// runners expect and re-introducing a leading dash risk).
48				return strings.TrimLeft(strings.Join(lines[i+1:], "\n"), "\r\n")
49			}
50		}
51		return content // no closing delimiter; leave as-is
52	}
53	
54	// renderDistillPrompt substitutes the active taxonomy into the template's
55	// ${TAXONOMY_BLOCK} marker. The rendered prompt is what gets passed to the seed
56	// agent as its system prompt; the line-numbered transcript chunk is the input.
57	func renderDistillPrompt(taxonomy factTaxonomy) (string, error) {
58		template, err := distillTemplate()
59		if err != nil {
60			return "", err
61		}
62		if !strings.Contains(template, distillTaxonomyMarker) {
63			return "", fmt.Errorf("distill template missing %s marker", distillTaxonomyMarker)
64		}
65		return strings.ReplaceAll(template, distillTaxonomyMarker, factTaxonomyBlock(taxonomy)), nil
66	}
