68	// factTaxonomyBlock renders the taxonomy as the prompt section the agent uses to
69	// classify facts: the fixed top-level categories and the known three-level
70	// paths with descriptions. Output is deterministic (sorted) so the rendered
71	// prompt is stable across runs.
72	func factTaxonomyBlock(taxonomy factTaxonomy) string {
73		var b strings.Builder
74		b.WriteString("## Taxonomy\n\n")
