86		if len(taxonomy.Paths) > 0 {
87			b.WriteString("\nKnown paths (prefer these):\n\n")
88			paths := append([]factPathDef(nil), taxonomy.Paths...)
89			sort.Slice(paths, func(i, j int) bool { return paths[i].Path < paths[j].Path })
90			for _, def := range paths {
91				if def.Description != "" {
92					fmt.Fprintf(&b, "- `%s` — %s\n", def.Path, def.Description)
93				} else {
94					fmt.Fprintf(&b, "- `%s`\n", def.Path)
95				}
96			}
97		}
98		return b.String()
99	}
100	
101	// distillAgentCommandArgs builds the argv that runs the seed agent with the
102	// rendered distillation prompt. It mirrors seedAgentCommandArgs: the prompt is
103	// the agent's system prompt and the transcript chunk is supplied on stdin. The
104	// no-agent mode ("none") has no command — distillation is agent-required.
105	func distillAgentCommandArgs(agent string, agentCommand []string, prompt string) ([]string, error) {
106		switch agent {
107		case "command":
108			if len(agentCommand) == 0 {
109				return nil, errors.New("--agent-command is required when --agent command")
110			}
111			return append([]string(nil), agentCommand...), nil
112		case "codex":
113			return []string{"codex", "exec", "--skip-git-repo-check", "--ephemeral", "--ignore-user-config", "--ignore-rules", "--sandbox", "read-only", prompt}, nil
114		case "claude-code":
115			return []string{"claude", "--print", "--no-session-persistence", "--setting-sources", "user", "--strict-mcp-config", "--mcp-config", "{\"mcpServers\":{}}", "--disable-slash-commands", "--permission-mode", "dontAsk", "--tools", "", "--system-prompt", prompt}, nil
116		case "none", "":
117			return nil, errors.New("distillation requires an agent; --agent none has nothing to run")
118		default:
119			return nil, fmt.Errorf("unsupported --agent %q", agent)
120		}
121	}
122	
123	// injectAgentModel inserts a `--model <model>` flag into a codex/claude-code argv
124	// so the distill run can pin a specific model (e.g. gpt-5.3-codex-spark). It is a
125	// no-op for an empty model or any other agent (the `command` agent carries its
126	// own argv). The flag is inserted early — after `codex exec` / after `claude` —
127	// where both CLIs accept it, ahead of the trailing prompt argument.
128	func injectAgentModel(args []string, agent, model string) []string {
129		if model == "" {
130			return args
131		}
132		switch agent {
133		case "codex":
134			if len(args) >= 2 && args[0] == "codex" && args[1] == "exec" {
135				return append(args[:2:2], append([]string{"--model", model}, args[2:]...)...)
136			}
137		case "claude-code":
138			if len(args) >= 1 && args[0] == "claude" {
139				return append(args[:1:1], append([]string{"--model", model}, args[1:]...)...)
140			}
141		}
142		return args
143	}
144	
145	// injectAgentEffort pins the reasoning effort for a codex/claude-code argv built by
146	// distillAgentCommandArgs/seedAgentCommandArgs — codex via `--config model_reasoning_effort=<e>`,
147	// claude-code via `--effort <e>` (the same forms the benchmark harness uses). It mirrors
148	// injectAgentModel: a no-op for an empty effort, the `command` agent, or an unrecognized shape,
149	// and inserts early so the trailing prompt argument stays last.
150	func injectAgentEffort(args []string, agent, effort string) []string {
151		if effort == "" {
152			return args
153		}
154		switch agent {
155		case "codex":
156			if len(args) >= 2 && args[0] == "codex" && args[1] == "exec" {
157				return append(args[:2:2], append([]string{"--config", "model_reasoning_effort=" + effort}, args[2:]...)...)
158			}
159		case "claude-code":
160			if len(args) >= 1 && args[0] == "claude" {
161				return append(args[:1:1], append([]string{"--effort", effort}, args[1:]...)...)
162			}
163		}
164		return args
165	}
166	
167	// distilledFactsFromOutput parses the agent's line-based output for one
168	// transcript chunk into fact records. Each emitted line is
169	// `[kind<TAB>]path[,path]<TAB>fact` — the leading KIND column is optional and
170	// falls back to deterministic inference when absent or invalid. Lines are
171	// dropped (with a warning) when they have no
172	// tab, no syntactically valid path, or no path whose top-level category exists
173	// in the active taxonomy — the taxonomy's top levels are fixed, so a path under
174	// an unknown category cannot be trusted. Output is capped at factsMaxPerChunk;
175	// extra lines are dropped with a warning so a runaway agent cannot flood the
176	// store.
177	//
178	// Every produced record cites the supplied anchor as its provenance and is
179	// stamped origin=distilled, status=active. Ids are content-derived, so the same
180	// statement from the same chunk is idempotent across reruns.
181	func distilledFactsFromOutput(output string, taxonomy factTaxonomy, anchor factAnchor, branch string, now time.Time) ([]factRecord, []string) {
182		var records []factRecord
183		var warnings []string
184		capped := false
185		for _, raw := range strings.Split(output, "\n") {
186			line := strings.TrimRight(raw, "\r")
187			if strings.TrimSpace(line) == "" {
188				continue
189			}
190			// Some models (seen with gpt-5.3-codex-spark) emit the separator as a
191			// literal backslash-t escape instead of a real tab character. Recover the
192			// first literal `\t` (the leading structural separator); when that leading
193			// field is a KIND there is a second structural separator (kind|path) to
194			// recover too. Any further literal `\t` belongs to the fact text and is
195			// left intact — so a legacy `path\tfact-with-\t` keeps its in-text escape
196			// (only one structural tab) while a new `kind\tpath\tfact` recovers both.
197			if !strings.ContainsRune(line, '\t') && strings.Contains(line, `\t`) {
198				line = strings.Replace(line, `\t`, "\t", 1)
199				if fields := strings.SplitN(line, "\t", 2); len(fields) == 2 && validFactKind(fields[0]) {
200					line = fields[0] + "\t" + strings.Replace(fields[1], `\t`, "\t", 1)
201				}
202			}
203			if !strings.ContainsRune(line, '\t') {
204				// Prose / preamble the template forbids; ignore quietly unless it
205				// looks like an attempted fact (contains a path-like token).
206				if strings.Contains(line, ".") && strings.Contains(line, " ") {
207					warnings = append(warnings, "dropped line without tab separator: "+truncateString(strings.TrimSpace(line), 120))
208				}
209				continue
210			}
211			kind, rawPaths, text := parseFactLine(line)
212			if text == "" {
213				continue
214			}
215			paths := normalizeFactPaths(rawPaths)
216			paths = filterFactPathsByTaxonomy(paths, taxonomy, &warnings)
217			if len(paths) == 0 {
218				warnings = append(warnings, "dropped fact with no valid taxonomy path: "+truncateString(text, 120))
219				continue
220			}
221			if len(records) >= factsMaxPerChunk {
222				capped = true
223				continue
224			}
225			text = truncateString(text, distillFactMaxTextSize)
226			if kind == "" {
227				kind = inferFactKind(paths, text) // agent omitted/violated kind → deterministic fallback
228			}
229			records = append(records, factRecord{
230				ID:         factRecordID(text, paths),
231				Paths:      paths,
232				Kind:       kind,
233				Locus:      factLocus(text),
234				Text:       text,
235				Branch:     branch,
236				Origin:     factOriginDistilled,
237				Status:     factStatusActive,
238				Provenance: []factAnchor{anchor},
239				CreatedAt:  now,
240				UpdatedAt:  now,
241			})
242		}
243		if capped {
244			warnings = append(warnings, fmt.Sprintf("chunk produced more than %d facts; extra lines dropped", factsMaxPerChunk))
245		}
246		return records, warnings
247	}
248	
249	// parseFactLine parses one distill output line into (kind, raw paths, fact
250	// text), tolerating three shapes the agent actually produces:
251	//
252	//	path[,path]<TAB>fact                  — legacy 2-field, kind inferred ("")
253	//	kind<TAB>path[,path]<TAB>fact         — the new column, kind honored
254	//	<word><TAB>path[,path]<TAB>fact       — an unrecognized leading word (a kind
255	//	                                        synonym): dropped, kind inferred
256	//
257	// The grammar is "an optional single leading non-path token, then path-blocks,
258	// then text". It first tries reading path-blocks from the front (the legacy
259	// case); only if that yields no path does it drop one leading field and retry,
260	// so a genuine path-first line is never misread and a malformed line (no path
261	// either way) still falls through to be dropped by the caller. This recovers
262	// the fact whether the agent emits an exact kind, a near-miss synonym, or no
263	// kind at all — instead of silently dropping a line whose leading token is not
264	// in the closed set.
265	func parseFactLine(line string) (string, []string, string) {
266		if paths, text := splitFactLine(line); len(normalizeFactPaths(paths)) > 0 {
267			return "", paths, text // path-block leads: legacy form, no kind column
268		}
269		// Leading field is not a path-block — it may be a kind (or a synonym). Drop
270		// exactly one field and retry; accept only if that reveals a valid path.
271		fields := strings.SplitN(line, "\t", 2)
272		if len(fields) == 2 {
273			if paths, text := splitFactLine(fields[1]); len(normalizeFactPaths(paths)) > 0 {
274				if lead := strings.ToLower(strings.TrimSpace(fields[0])); validFactKind(lead) {
275					return lead, paths, text
276				}
277				return "", paths, text // unrecognized leading word → infer the kind
278			}
279		}
280		// No path either way: return the legacy parse so the caller drops it with the
281		// existing "no valid taxonomy path" warning.
282		paths, text := splitFactLine(line)
283		return "", paths, text
284	}
285	
286	// splitFactLine separates a distill output line into its path tokens and fact
287	// text. The template specifies `path[,path]<TAB>fact`, but agents sometimes
288	// separate multiple paths with tabs instead of commas (`path<TAB>path<TAB>fact`),
289	// which would otherwise leak a path into the fact text. It therefore consumes
290	// leading tab-separated fields for as long as each is a path-block (comma-joined
291	// valid paths, no prose), and treats the remainder as the fact. Prose cannot
292	// match the strict path pattern (it contains spaces), so a fact is never
293	// mistaken for a path.
294	func splitFactLine(line string) ([]string, string) {
295		fields := strings.Split(line, "\t")
296		var paths []string
297		i := 0
298		for i < len(fields)-1 { // always leave at least one field for the text
299			field := strings.TrimSpace(fields[i])
300			if !fieldLooksLikePaths(field) {
301				break
302			}
303			paths = append(paths, strings.Split(field, ",")...)
304			i++
305		}
306		text := strings.TrimSpace(strings.Join(fields[i:], " "))
307		return paths, text
308	}
309	
310	// fieldLooksLikePaths reports whether a tab-separated field is entirely a
311	// path-block: one or more comma-joined, syntactically valid taxonomy paths.
312	func fieldLooksLikePaths(field string) bool {
313		if field == "" {
314			return false
315		}
316		for _, part := range strings.Split(field, ",") {
317			if !validFactPath(strings.ToLower(strings.TrimSpace(part))) {
318				return false
319			}
320		}
321		return true
322	}
323	
324	// filterFactPathsByTaxonomy keeps only paths whose top-level category exists in
325	// the taxonomy, recording a warning for each dropped path. Paths are already
326	// syntactically valid (normalizeFactPaths ran first).
327	func filterFactPathsByTaxonomy(paths []string, taxonomy factTaxonomy, warnings *[]string) []string {
328		tops := factTaxonomyTopLevels(taxonomy)
329		kept := paths[:0:0]
330		for _, path := range paths {
331			if _, ok := tops[factTopLevel(path)]; ok {
332				kept = append(kept, path)
333				continue
334			}
335			*warnings = append(*warnings, fmt.Sprintf("dropped path under unknown category: %s", path))
336		}
337		return kept
338	}
